using System;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Media;
using System.Windows.Shapes;
using SplifyWin;
namespace Mcrf.Wpf {
 public sealed partial class MainWindow {
  string[] CompactPairColors{get{if(session==null||session.State.CompactAccent!="theme-pair")return null;var s=session.State;var colors=new[]{s.CompactDarkPrimary,s.CompactDarkSecondary,s.CompactLightPrimary,s.CompactLightSecondary};return colors.All(ValidCompactColor)?colors:null;}}
  Brush AppearanceBackground(string legacy,bool light){var pair=CompactPairColors;if(pair==null)return light?Brush("#FFF4F6F7"):CompactGradient(CompactSafeDarkColor(legacy),"#14151A20");var basis=CompactColor(light?"#F4F6F7":"#0E1217");var first=CompactMix(basis,CompactColor(pair[light?2:0]),light?.025:.04);var last=CompactMix(basis,CompactColor(pair[light?3:1]),light?.04:.07);var brush=new LinearGradientBrush(first,last,35);brush.Freeze();return brush;}
  static string NormalizeAppearanceColor(string value){string hex=(value??"").Trim();if(hex.StartsWith("#",StringComparison.Ordinal))hex=hex.Substring(1);if(!System.Text.RegularExpressions.Regex.IsMatch(hex,@"^[0-9a-fA-F]{6}$"))throw new FormatException("Цвет: # и шесть символов, например #28A77A.");return "#"+hex.ToUpperInvariant();}
  async Task<bool> SaveAppearancePair(string[] values){if(values==null||values.Length!=4)throw new FormatException("Укажите четыре цвета.");var next=values.Select(NormalizeAppearanceColor).ToArray();var s=session.State;var previous=new[]{s.CompactDarkPrimary,s.CompactDarkSecondary,s.CompactLightPrimary,s.CompactLightSecondary,s.CompactAccent,s.CompactAccentColor,s.CompactCardColor,s.CompactBackgroundColor};bool saved=false;await Run(async()=>{s.CompactDarkPrimary=next[0];s.CompactDarkSecondary=next[1];s.CompactLightPrimary=next[2];s.CompactLightSecondary=next[3];s.CompactAccent="theme-pair";s.CompactAccentColor=next[0];s.CompactCardColor="#171C22";s.CompactBackgroundColor="#0E1217";await session.Save();saved=true;},()=>{s.CompactDarkPrimary=previous[0];s.CompactDarkSecondary=previous[1];s.CompactLightPrimary=previous[2];s.CompactLightSecondary=previous[3];s.CompactAccent=previous[4];s.CompactAccentColor=previous[5];s.CompactCardColor=previous[6];s.CompactBackgroundColor=previous[7];});if(saved&&!closing&&!closeRequested){ApplyWorkspacePalette(false);Page("Журнал");}return saved;}
  void AppearanceGallery(){
   var dialog=Dialog("Палитры оформления",390,600);dialog.ResizeMode=ResizeMode.NoResize;var panel=new DockPanel{Margin=new Thickness(14)};var search=new TextBox{Name="appearancePaletteSearch",Height=36,Margin=new Thickness(0,0,0,10),ToolTip="Поиск палитры"};System.Windows.Automation.AutomationProperties.SetName(search,"Поиск палитры");DockPanel.SetDock(search,Dock.Top);panel.Children.Add(search);var footer=new StackPanel();var feedback=Text("40 палитр · отдельные цвета для обеих тем",11);feedback.Name="appearancePaletteFeedback";footer.Children.Add(feedback);var cancel=Button("Закрыть",()=>dialog.Close());cancel.IsCancel=true;footer.Children.Add(cancel);DockPanel.SetDock(footer,Dock.Bottom);panel.Children.Add(footer);var grid=new UniformGrid{Columns=2};var scroll=new ScrollViewer{Content=grid,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};panel.Children.Add(scroll);bool saving=false;Action render=()=>{grid.Children.Clear();var filtered=AppearancePresets.All.Where(p=>p.Name.IndexOf(search.Text.Trim(),StringComparison.CurrentCultureIgnoreCase)>=0).ToArray();feedback.Text=filtered.Length==0?"Палитры не найдены":filtered.Length+" палитр · цвета обеих тем";foreach(var preset in filtered){var selected=preset;var contents=new StackPanel();var dots=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};foreach(var color in selected.Colors.Skip(CompactLight?2:0).Take(2))dots.Children.Add(new Ellipse{Width=13,Height=13,Fill=Brush(color),Margin=new Thickness(3)});contents.Children.Add(dots);contents.Children.Add(new TextBlock{Text=selected.Name,TextWrapping=TextWrapping.Wrap,TextAlignment=TextAlignment.Center,FontSize=11,Foreground=Brush(CompactPrimary)});var button=Button("",async()=>{if(saving)return;saving=true;grid.IsEnabled=search.IsEnabled=cancel.IsEnabled=false;try{if(await SaveAppearancePair(selected.Colors)){saving=false;dialog.DialogResult=true;}else feedback.Text="Не удалось сохранить палитру. Выбор не изменён.";}finally{saving=false;grid.IsEnabled=search.IsEnabled=cancel.IsEnabled=true;}});button.Style=(Style)FindResource("PaletteChoice");button.Background=Brush(CompactLight?"#E8ECEE":"#20262D");button.Content=contents;button.Tag=selected;button.Name="appearancePalette"+Array.IndexOf(AppearancePresets.All,selected);button.MinHeight=64;button.Margin=new Thickness(3);button.Foreground=Brush(CompactPrimary);System.Windows.Automation.AutomationProperties.SetName(button,selected.Name);button.BorderThickness=new Thickness(CompactPairColors!=null&&CompactPairColors.SequenceEqual(selected.Colors)?2:0);button.BorderBrush=Brush(CompactVisualAccent);System.Windows.Automation.AutomationProperties.SetItemStatus(button,button.BorderThickness.Left==2?"Выбрана":"");grid.Children.Add(button);}};search.TextChanged+=(s,e)=>render();render();dialog.Closing+=(s,e)=>{if(saving)e.Cancel=true;};dialog.Content=panel;dialog.Loaded+=(s,e)=>search.Focus();ApplyCompactControlPalette(panel);dialog.ShowDialog();
  }
  void AppearanceCustomColors(){
   var dialog=Dialog("Цвета оформления",390,580);dialog.MaxHeight=dialog.Height;dialog.SizeToContent=SizeToContent.Height;dialog.ResizeMode=ResizeMode.NoResize;var panel=new StackPanel{Margin=new Thickness(16)};panel.Children.Add(Text("Отдельные пары для тёмной и светлой тем. Яркость акцентов подстраивается для читаемости.",12));var initial=CompactPairColors??new[]{CompactAccentColor,"#AA91F5","#167C70","#C8C3EA"};var labels=new[]{"Тёмная тема · первый цвет","Тёмная тема · второй цвет","Светлая тема · первый цвет","Светлая тема · второй цвет"};var fields=initial.Select((value,i)=>new TextBox{Name="appearanceColor"+i,Text=value,Height=36,MaxLength=16,Margin=new Thickness(0,0,0,6)}).ToArray();for(int i=0;i<fields.Length;i++){System.Windows.Automation.AutomationProperties.SetName(fields[i],labels[i]);panel.Children.Add(Field(labels[i],fields[i]));}var feedback=Text("",12);feedback.Name="appearanceColorFeedback";feedback.MaxHeight=52;feedback.Visibility=Visibility.Collapsed;panel.Children.Add(feedback);bool saving=false;Button save=null,cancel=null;save=Button("Сохранить",async()=>{if(saving)return;saving=true;foreach(var field in fields)field.IsEnabled=false;save.IsEnabled=cancel.IsEnabled=false;try{if(await SaveAppearancePair(fields.Select(f=>f.Text).ToArray())){saving=false;dialog.DialogResult=true;}else{feedback.Text="Не удалось сохранить цвета. Настройки не изменены.";feedback.Visibility=Visibility.Visible;}}catch(FormatException ex){feedback.Text=ex.Message;feedback.Visibility=Visibility.Visible;}finally{saving=false;foreach(var field in fields)field.IsEnabled=true;save.IsEnabled=cancel.IsEnabled=true;feedback.Foreground=Brush(CompactError);}});save.Name="appearanceColorSave";cancel=Button("Отмена",()=>dialog.DialogResult=false);cancel.Name="appearanceColorCancel";cancel.IsCancel=true;panel.Children.Add(Toolbar(save,cancel));dialog.Closing+=(s,e)=>{if(saving)e.Cancel=true;};dialog.Content=panel;ApplyCompactControlPalette(panel);dialog.ShowDialog();
  }
 }
}
